    if (canWin($HPY, $ATKY, $DEFY, $HPM, $ATKM, $DEFM)) {
        echo 0 . "\n";
        return;
    }

    $minCost = PHP_INT_MAX;

    // We need to find the minimum cost to buy some HP, ATK, DEF upgrades
    // Let's think about the constraints:
    // - HPY can be increased up to some reasonable limit
    // - ATKY can be increased up to some reasonable limit
    // - DEFY can be increased up to some reasonable limit

    // The monster has HPM HP. Yang needs to deal HPM damage total.
    // Each second, Yang deals max(0, ATKY - DEFM) damage.
    // So Yang needs at least ceil(HPM / max(1, ATKY - DEFM)) seconds to kill the monster.
    // But also, Yang must survive that many seconds.
    // Each second, Yang takes max(0, ATKM - DEFY) damage.
    // So Yang needs HPY > (number of seconds) * max(0, ATKM - DEFY)
    // Actually, Yang wins if after the same second the monster's HP <= 0 and Yang's HP > 0.
    // So if it takes T seconds to kill the monster, Yang needs HPY > T * max(0, ATKM - DEFY)
    // Wait, let me re-read: "Once monster's HP ≤ 0 and the same time Master Yang's HP > 0, Master Yang wins."
    // So both happen simultaneously each second. After T seconds, monster HP <= 0. At that same time, Yang's HP must be > 0.
    // Yang's HP after T seconds = HPY - T * max(0, ATKM - DEFY)
    // We need HPY - T * max(0, ATKM - DEFY) > 0
    // So HPY > T * max(0, ATKM - DEFY)

    // T = ceil(HPM / max(1, ATKY - DEFM)) if ATKY > DEFM, else infinite (can't kill)

    // Strategy: iterate over possible ATK upgrades and DEF upgrades, and compute the minimum HP needed.
    // Since all values are between 1 and 100, the upgrades don't need to be too large.
    // Let's bound the search:
    // - ATK upgrade: from 0 to maybe 200 (since ATKM <= 100, DEFM <= 100, so ATKY - DEFM can be up to 100+200-1=299, but we don't need that much)
    // - DEF upgrade: from 0 to maybe 100 (since ATKM <= 100, DEFY + upgrade >= ATKM means no damage taken)
    // - HP upgrade: from 0 to maybe 10000 (to be safe)

    // Actually, let's think more carefully.
    // Let newATK = ATKY + addATK, newDEF = DEFY + addDEF, newHP = HPY + addHP
    // Cost = addHP * h + addATK * a + addDEF * d

    // We need:
    // 1. newATK > DEFM (otherwise can't kill monster)
    // 2. Let dmgPerSec = newATK - DEFM
    // 3. T = ceil(HPM / dmgPerSec)
    // 4. dmgToYangPerSec = max(0, ATKM - newDEF)
    // 5. newHP > T * dmgToYangPerSec

    // So for given addATK and addDEF, we can compute the minimum addHP needed.

    // Bounds:
    // addATK: 0 to 200 (since ATKY <= 100, DEFM <= 100, so ATKY + addATK > DEFM means addATK > DEFM - ATKY, and we don't need more than, say, 200)
    // addDEF: 0 to 100 (since ATKM <= 100, if DEFY + addDEF >= ATKM, then dmgToYangPerSec = 0, so no HP needed beyond what's already there)
    // addHP: 0 to 10000 (to be safe)

    for ($addATK = 0; $addATK <= 200; $addATK++) {
        $newATK = $ATKY + $addATK;
        if ($newATK <= $DEFM) {
            continue; // Can't kill monster
        }

        for ($addDEF = 0; $addDEF <= 100; $addDEF++) {
            $newDEF = $DEFY + $addDEF;
            $dmgToYangPerSec = max(0, $ATKM - $newDEF);

            $dmgPerSec = $newATK - $DEFM;
            $T = (int)ceil($HPM / $dmgPerSec);

            if ($dmgToYangPerSec == 0) {
                $minHPNeeded = 1; // Yang just needs to have HP > 0
            } else {
                $minHPNeeded = $T * $dmgToYangPerSec + 1;
            }

            if ($minHPNeeded <= $HPY) {
