}

function canWin($HPY, $ATKY, $DEFY, $HPM, $ATKM, $DEFM) {
    if ($ATKY <= $DEFM) {
        return false;
    }
    $dmgPerSec = $ATKY - $DEFM;
    $T = (int)ceil($HPM / $dmgPerSec);
    $dmgToYangPerSec = max(0, $ATKM - $DEFY);
    $yangHPAfter = $HPY - $T * $dmgToYangPerSec;
    return $yangHPAfter > 0;
}

